        getHint(state, results) {
            if (!results) return null;
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (results.crisis) return t('hint_crisis');
            if (results.roi < -20) return t('hint_loss');
            if (state.domainState.complianceScore < 70) return t('hint_compliance');
            if (state.decisions.megaPct >= 40) return t('hint_mega_heavy');
            if (state.decisions.organicPct < 10 && state.currentPeriod >= 4) return t('hint_organic');
            if (state.decisions.authenticity <= 3) return t('hint_authenticity');
            if (results.roi > 40) return t('hint_great_roi');
            return null;
        }

