        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalRevenue = history.reduce(function(s, r) { return s + (r.results && r.results.revenue || 0); }, 0);
            var totalProfit = history.reduce(function(s, r) { return s + (r.results && r.results.profit || 0); }, 0);
            var totalSpend = history.length * 500000;
            var roi = totalSpend > 0 ? ((totalProfit - totalSpend) / totalSpend) * 100 : 0;
            var finalAwareness = history[history.length - 1].results ? history[history.length - 1].results.awareness : 35;
            var finalCompliance = history[history.length - 1].results ? history[history.length - 1].results.compliance : 100;

            var performance = 'Developing';
            if (roi > 30 && finalAwareness > 55 && finalCompliance >= 85) performance = 'Excellent';
            else if (roi > 0 && finalAwareness > 45 && finalCompliance >= 75) performance = 'Strong';
            else if (roi > -30) performance = 'Adequate';
            else performance = 'Underperforming';

            var insights = [];
            if (roi < 0) insights.push('ROI is negative — incrementality-adjusted revenue is not covering creator spend.');
            if (finalCompliance < 80) insights.push('Compliance slipped — PROFECO disclosure rigor needs to be non-negotiable.');
            if (finalAwareness > 55) insights.push('Strong awareness lift — the creator portfolio cut through.');
            if (roi > 30 && finalAwareness > 50) insights.push('Exemplary balance of tier mix, authenticity and community investment.');
            if (insights.length === 0) insights.push('Solid baseline — iterate on tier mix and organic share next quarter.');

            var _last = history[history.length - 1].results || {};
            var overallScore = this._overallScore(totalProfit, history.length, finalAwareness, finalCompliance, _last.engagement || 0, _last.followers || 350000);
            return {
                overallScore: overallScore,
                score: overallScore,
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                roi: Math.round(roi * 10) / 10,
                finalAwareness: finalAwareness,
                finalCompliance: finalCompliance,
                performance: performance,
                insights: insights
            };
        }

        _overallScore(totalProfit, periods, awareness, compliance, engagement, followers) {
            var c = function (x) { return Math.max(0, Math.min(100, x)); };
            var spend = periods * this.STAGE_BUDGET;
            var roi = spend > 0 ? ((totalProfit - spend) / spend) * 100 : 0;
            var sRoi = c((roi + 60) / 100 * 100);
            var sAw = c((awareness - 35) / 35 * 100);
            var sComp = c(compliance);
            var sEng = c(engagement / 8 * 100);
            var sFol = c((followers / 350000 - 1) / 0.5 * 100);
            return Math.round(0.35 * sRoi + 0.25 * sAw + 0.20 * sComp + 0.10 * sEng + 0.10 * sFol);
        }

        _rateCreator(s) {
            return s >= 75 ? 'Excellent' : s >= 55 ? 'Strong' : s >= 35 ? 'Adequate' : 'Underperforming';
        }

